function i(t){if(!t)return"";const n=typeof t=="number"?t:new Date(t).getTime(),e=Date.now()-n,a=6e4,f=36e5,r=864e5;if(e<a)return"刚刚";if(e<f)return`${Math.floor(e/a)} 分钟前`;if(e<r)return`${Math.floor(e/f)} 小时前`;if(e<30*r)return`${Math.floor(e/r)} 天前`;const o=new Date(n);return`${o.getFullYear()}-${String(o.getMonth()+1).padStart(2,"0")}-${String(o.getDate()).padStart(2,"0")}`}function c(t){return t>=1e4?(t/1e4).toFixed(1).replace(/\.0$/,"")+"w":t>=1e3?(t/1e3).toFixed(1).replace(/\.0$/,"")+"k":String(t)}export{c,i as t};
